Inductive List = nil Unit | cons {Int, List};

first_or_zero = fix (\f: List -> Int. \xs: List.
  match xs with
    nil _ -> 0
  | cons {h, t} -> h
  end
);

main = first_or_zero;

Inductive List = nil Unit | cons {Int, List};

count_two = fix (\f: List -> Int. \xs: List.
  match xs with
    nil _ -> 0
  | cons {h, t} -> if (== h 2) then + 1 (f t) else f t
  end
);

main = count_two;

Inductive List = nil Unit | cons {Int, List};

sum_below_five = fix (\f: List -> Int. \xs: List.
  match xs with
    nil _ -> 0
  | cons {h, t} -> if (< h 5) then + h (f t) else f t
  end
);

main = sum_below_five;
